using System;using System.IO;using System.Reflection;using BunjangAuto;
class SetupGateTests {
[STAThread]static int Main(){AppDomain.CurrentDomain.AssemblyResolve+=delegate(object s,ResolveEventArgs a){using(var x=Assembly.GetExecutingAssembly().GetManifestResourceStream("lib."+new AssemblyName(a.Name).Name+".dll")){if(x==null)return null;using(var m=new MemoryStream()){x.CopyTo(m);return Assembly.Load(m.ToArray());}}};return Run();}
[System.Runtime.CompilerServices.MethodImpl(System.Runtime.CompilerServices.MethodImplOptions.NoInlining)] static int Run(){try{Paths.EnsureAll(); string token=File.ReadAllText(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData),"BunjangAuto","license.key")); System.Windows.Forms.Application.EnableVisualStyles(); AppFont.Init(); ThemeService.Init(new AppSettings()); var timer=new System.Windows.Forms.Timer{Interval=150};timer.Tick+=delegate{foreach(System.Windows.Forms.Form f in System.Windows.Forms.Application.OpenForms){if(f is LicenseForm){timer.Stop();string msg;if(!LicenseGate.TryActivate(token,out msg))throw new Exception(msg);f.DialogResult=System.Windows.Forms.DialogResult.OK;break;}}};timer.Start();if(!LicenseGate.Check())throw new Exception("Fresh UI gate failed"); timer.Dispose(); Console.WriteLine("PASS fresh activation dialog");for(int i=0;i<3;i++){if(!LicenseGate.Recheck())throw new Exception("License verification failed");Console.WriteLine("Valid license: "+LicenseGate.LastInfo.Name);UsageQuota.EnsureReady(); Console.WriteLine("PASS setup usage round "+i);}return 0;}catch(Exception ex){Console.WriteLine(ex);return 1;}}
}